package local.connecthead.ui

import androidx.compose.foundation.Canvas
import androidx.compose.foundation.isSystemInDarkTheme
import androidx.compose.foundation.layout.aspectRatio
import androidx.compose.runtime.Composable
import androidx.compose.runtime.remember
import androidx.compose.ui.Modifier
import androidx.compose.ui.graphics.Brush
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.drawscope.scale
import androidx.compose.ui.graphics.vector.PathParser

/**
 * "CONNECT HEAD" in the manner of the silver Sony wordmark: wide Clarendon capitals with a
 * brushed-metal fill. The letters are outlines traced from Superclarendon Bold (so the font
 * itself isn't shipped); in light mode the metal is darker steel so it reads on paper.
 */
@Composable
fun Wordmark(modifier: Modifier = Modifier) {
    val dark = isSystemInDarkTheme()
    val path = remember { PathParser().parsePathString(WORDMARK_PATH).toPath() }
    val metal = if (dark) listOf(0f to Color(0xFFF4F4F2), 0.45f to Color(0xFFB9BBBD), 0.5f to Color(0xFF8A8D90),
                                 0.75f to Color(0xFFC9CBCC), 1f to Color(0xFF9A9C9E))
                else listOf(0f to Color(0xFF8E9194), 0.45f to Color(0xFF5E6164), 0.5f to Color(0xFF3B3E41),
                            0.75f to Color(0xFF66696C), 1f to Color(0xFF4A4D50))
    Canvas(modifier.aspectRatio(WORDMARK_WIDTH / WORDMARK_HEIGHT)) {
        val k = size.width / WORDMARK_WIDTH
        scale(k, k, pivot = androidx.compose.ui.geometry.Offset.Zero) {
            drawPath(path, Brush.verticalGradient(*metal.toTypedArray(), startY = 0f, endY = WORDMARK_HEIGHT))
        }
    }
}

